// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// Prod (Vercel): TURSO_DATABASE_URL + TURSO_AUTH_TOKEN drive `prisma db push` /
// `prisma generate` against Turso. Local dev: falls back to DATABASE_URL
// (sqlite file). See docs/TURSO.md.
const tursoUrl = process.env["TURSO_DATABASE_URL"];
const datasourceUrl = tursoUrl
  ? `${tursoUrl}${tursoUrl.includes("?") ? "&" : "?"}authToken=${process.env["TURSO_AUTH_TOKEN"]}`
  : process.env["DATABASE_URL"];

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: datasourceUrl,
  },
});
